1250	fn base64_encode(bytes: &[u8]) -> String {
1251	    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
1252	
1253	    let mut encoded = String::with_capacity(bytes.len().div_ceil(3) * 4);
1254	    for chunk in bytes.chunks(3) {
1255	        let first = chunk[0];
1256	        let second = chunk.get(1).copied().unwrap_or(0);
1257	        let third = chunk.get(2).copied().unwrap_or(0);
1258	
1259	        encoded.push(TABLE[usize::from(first >> 2)] as char);
1260	        encoded.push(TABLE[usize::from(((first & 0b0000_0011) << 4) | (second >> 4))] as char);
1261	        if chunk.len() > 1 {
1262	            encoded.push(TABLE[usize::from(((second & 0b0000_1111) << 2) | (third >> 6))] as char);
1263	        } else {
1264	            encoded.push('=');
1265	        }

