1652	fn copy_character_selection(lines: &[String], start: TextPosition, end: TextPosition) -> String {
1653	    if start.line == end.line {
1654	        return slice_chars(&lines[start.line], start.column, end.column.saturating_add(1));
1655	    }
1656	
1657	    let mut copied = Vec::new();
1658	    copied.push(slice_chars(
1659	        &lines[start.line],
1660	        start.column,
1661	        line_char_len(&lines[start.line]),
1662	    ));
1663	    for line in &lines[start.line + 1..end.line] {
1664	        copied.push(line.clone());
1665	    }
1666	    copied.push(slice_chars(&lines[end.line], 0, end.column.saturating_add(1)));
1667	    copied.join("\n")
1668	}
