1674	    let end_column = anchor.column.max(cursor.column).saturating_add(1);
1675	    lines[start_line..=end_line]
1676	        .iter()
1677	        .map(|line| slice_chars(line, start_column, end_column))
1678	        .collect::<Vec<_>>()
1679	        .join("\n")
